import{_ as c,C as r,o as l,c as h,j as d,a as e,E as o,a5 as i}from"./chunks/framework.Dep_XxFZ.js";const q=JSON.parse('{"title":"分页","description":"","frontmatter":{},"headers":[],"relativePath":"components/pagination.md","filePath":"components/pagination.md","lastUpdated":1787363843000}'),s={name:"components/pagination.md"},g={id:"分页",tabindex:"-1"};function p(b,t,u,m,P,x){const n=r("Badge"),a=r("XhDemo");return l(),h("div",null,[d("h1",g,[t[0]||(t[0]=e("分页 ",-1)),o(n,{type:"info",text:"pagination"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#分页","aria-label":'Permalink to "分页 <Badge type="info" text="pagination" />"'},"​",-1))]),t[3]||(t[3]=i('<p>把一份很长的结果切成一页一页，并给出当前位置与去处。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>结果集很大且用户需要跳到确定的位置、或需要可分享的页码地址。</li><li>需要知道一共有多少条。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>内容是时间流、用户只关心&quot;再来一些&quot;：用<a href="./infinite-scroll">无限滚动</a>。</li><li>结果条数很少：一次全给。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>count</code> 给的是总条数不是总页数。</li><li>页码序列由 <code>root</code> 的插槽交出来，作者照着渲染条目与省略号；不渲染序列也行，只留上一页 / 下一页。</li><li><code>siblingCount</code> 决定当前页两侧各留几页，序列长度恒定，切页时省略号左右挪、按钮不抖。</li><li><code>dir</code> 只作用于排版：&quot;上一页&quot;永远是 <code>page - 1</code>，不随书写方向翻转。</li><li>换 <code>pageSize</code> 后总页数重算，越界的当前页被夹回末页。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>count 给的是总条数不是总页数；页码序列由 root 的插槽交出来，作者照着渲染 item 与省略号</p>',10)),o(a,{src:"pagination/01-basic"}),t[4]||(t[4]=d("h3",{id:"受控与切片",tabindex:"-1"},[e("受控与切片 "),d("a",{class:"header-anchor",href:"#受控与切片","aria-label":'Permalink to "受控与切片"'},"​")],-1)),t[5]||(t[5]=d("p",null,"传了 page 就由宿主说了算；当前页决定从整份数据里切出哪一段",-1)),o(a,{src:"pagination/02-controlled"}),t[6]||(t[6]=d("h3",{id:"两侧页数",tabindex:"-1"},[e("两侧页数 "),d("a",{class:"header-anchor",href:"#两侧页数","aria-label":'Permalink to "两侧页数"'},"​")],-1)),t[7]||(t[7]=d("p",null,"sibling-count 决定当前页两侧各留几页，序列长度恒定，切页时省略号左右挪、按钮不抖",-1)),o(a,{src:"pagination/03-sibling-count"}),t[8]||(t[8]=d("h3",{id:"读屏文案",tabindex:"-1"},[e("读屏文案 "),d("a",{class:"header-anchor",href:"#读屏文案","aria-label":'Permalink to "读屏文案"'},"​")],-1)),t[9]||(t[9]=d("p",null,"translations 换掉 nav 地标名与各按钮的 aria-label，默认是英文",-1)),o(a,{src:"pagination/04-translations"}),t[10]||(t[10]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[11]||(t[11]=d("p",null,"tone 换的是当前页选中态的底色与文字色，这里预置第 3 页为当前页",-1)),o(a,{src:"pagination/05-tone"}),t[12]||(t[12]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[13]||(t[13]=d("p",null,"size 一档换掉页码格子的高度、内边距与字号，上一页 / 下一页与省略号一并跟着变",-1)),o(a,{src:"pagination/06-size"}),t[14]||(t[14]=d("h3",{id:"极简排布",tabindex:"-1"},[e("极简排布 "),d("a",{class:"header-anchor",href:"#极简排布","aria-label":'Permalink to "极简排布"'},"​")],-1)),t[15]||(t[15]=d("p",null,"页码序列不渲染也行，只留上一页 / 下一页与一行位置回显；先后顺序归作者",-1)),o(a,{src:"pagination/07-simple"}),t[16]||(t[16]=d("h3",{id:"快速跳页",tabindex:"-1"},[e("快速跳页 "),d("a",{class:"header-anchor",href:"#快速跳页","aria-label":'Permalink to "快速跳页"'},"​")],-1)),t[17]||(t[17]=d("p",null,"输入框按 Enter 调插槽给的 setPage；越界页码由它夹回合法区间",-1)),o(a,{src:"pagination/08-jumper"}),t[18]||(t[18]=d("h3",{id:"每页条数",tabindex:"-1"},[e("每页条数 "),d("a",{class:"header-anchor",href:"#每页条数","aria-label":'Permalink to "每页条数"'},"​")],-1)),t[19]||(t[19]=d("p",null,"pageSize 归宿主持有；换档后总页数重算，越界的当前页被夹回末页",-1)),o(a,{src:"pagination/09-page-size"}),t[20]||(t[20]=d("h3",{id:"整组禁用",tabindex:"-1"},[e("整组禁用 "),d("a",{class:"header-anchor",href:"#整组禁用","aria-label":'Permalink to "整组禁用"'},"​")],-1)),t[21]||(t[21]=d("p",null,"分页自己没有禁用开关：裹一层 disabled 的 fieldset，里面的按钮统一失效并脱出 Tab 序",-1)),o(a,{src:"pagination/10-disabled"}),t[22]||(t[22]=i('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-pagination&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhPaginationEllipsis</code> <code>XhPaginationItem</code> <code>XhPaginationNextTrigger</code> <code>XhPaginationPrevTrigger</code> <code>XhPaginationRoot</code></td></tr><tr><td>组合式函数</td><td><code>usePagination</code></td></tr><tr><td>状态机</td><td><code>paginationMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/pagination.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;pagination&quot;</code>：<strong><code>root</code></strong> · <code>prev-trigger</code> · <code>next-trigger</code> · <strong><code>item</code></strong> · <code>ellipsis</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>总条数（不是总页数）。总页数由它与 pageSize 算出。</td></tr><tr><td><code>pageSize</code></td><td><code>number</code></td><td></td><td>每页条数，默认 10；小于 1 的值一律按 1 处理。</td></tr><tr><td><code>page</code></td><td><code>number</code></td><td></td><td>当前页。给定即受控：内部不再自改，只发 onPageChange。</td></tr><tr><td><code>defaultPage</code></td><td><code>number</code></td><td></td><td>非受控初始页，默认 1。</td></tr><tr><td><code>siblingCount</code></td><td><code>number</code></td><td></td><td>当前页两侧各显示几页，默认 1。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，只作用于排版；上一页/下一页的语义不随之翻转，&quot;上一页&quot;永远是 page - 1。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;PaginationTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onPageChange</code></td><td><code>(details: PaginationPageChangeDetails) =&gt; void</code></td><td></td><td>页码变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>page-change</code></td><td><code>PaginationPageChangeDetails</code></td><td>页码变化；detail 为 <code>{ page: number, pageSize: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhPaginationRoot</code></td><td><code>default</code></td><td><code>PaginationRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>PAGE.SET</code> · <code>PAGE.PREV</code> · <code>PAGE.NEXT</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>usePagination</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>page</code></td><td><code>number</code></td><td>当前页，恒在 [1, max(totalPages, 1)] 内。</td></tr><tr><td><code>pageSize</code></td><td><code>number</code></td><td></td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>totalPages</code></td><td><code>number</code></td><td></td></tr><tr><td><code>pages</code></td><td><code>PaginationPage[]</code></td><td>页码序列，作者照着渲染 item 与 ellipsis。</td></tr><tr><td><code>pageRange</code></td><td><code>PaginationEntryRange</code></td><td>当前页对应的条目区间，1 基闭区间；无数据时是 { start: 0, end: 0 }。</td></tr><tr><td><code>previousPage</code></td><td><code>number | null</code></td><td>上一页页码；已在首页（或无数据）时为 null。</td></tr><tr><td><code>nextPage</code></td><td><code>number | null</code></td><td></td></tr><tr><td><code>setPage</code></td><td><code>(page: number) =&gt; void</code></td><td>页码会被夹进合法区间，越界入参不会写出越界的页。</td></tr><tr><td><code>goToPrevPage</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>goToNextPage</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>slice</code></td><td><code>&lt;V&gt;(data: readonly V[]) =&gt; V[]</code></td><td>按当前页从整份数据里切出这一页。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPrevTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getNextTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: PaginationItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getEllipsisProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in item</td><td>跳到该页码（原生按钮激活，平台把按键翻成 click）</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in prev-trigger, 非首页</td><td>回上一页；首页时按钮是原生 disabled，焦点根本落不上去</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in next-trigger, 非末页</td><td>进下一页；末页时按钮是原生 disabled</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus in root</td><td>逐个走过每个可用按钮——分页不做 roving tabindex，用户要能 Tab 到某一页再确认；禁用的首尾按钮自动脱序</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>label.root</td></tr><tr><td><code>prev-trigger</code></td><td><code>aria-label</code></td><td>label.prevTrigger</td></tr><tr><td><code>next-trigger</code></td><td><code>aria-label</code></td><td>label.nextTrigger</td></tr><tr><td><code>item</code></td><td><code>aria-current</code></td><td>&#39;page&#39; | undefined</td></tr><tr><td><code>item</code></td><td><code>aria-label</code></td><td>label.item(item.page)</td></tr><tr><td><code>ellipsis</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/pagination.css</code> 按部件选择：<code>[data-scope=&quot;pagination&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>prev-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>next-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-current</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-pagination-ellipsis-fg</code> · <code>--xh-pagination-font-size</code> · <code>--xh-pagination-gap</code> · <code>--xh-pagination-item-bg</code> · <code>--xh-pagination-item-bg-active</code> · <code>--xh-pagination-item-bg-hover</code> · <code>--xh-pagination-item-bg-selected</code> · <code>--xh-pagination-item-bg-selected-active</code> · <code>--xh-pagination-item-bg-selected-hover</code> · <code>--xh-pagination-item-border-selected</code> · <code>--xh-pagination-item-border-selected-active</code> · <code>--xh-pagination-item-border-selected-hover</code> · <code>--xh-pagination-item-fg</code> · <code>--xh-pagination-item-fg-selected</code> · <code>--xh-pagination-item-font-weight</code> · <code>--xh-pagination-item-h</code> · <code>--xh-pagination-item-min-size</code> · <code>--xh-pagination-item-px</code> · <code>--xh-pagination-item-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./table">表格</a>、<a href="./list">列表</a>配合；整组禁用时裹一层 <code>disabled</code> 的 <code>fieldset</code>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>把当前页写进地址，用户刷新或分享才回得到原处。</li><li>数据在途时不要把分页整个卸载，否则每次翻页布局都跳一下。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>已知总数却不显示，用户无法判断还要翻多久。</li><li>把 <code>count</code> 当成总页数传进来：序列会短一大截。</li></ul>',45))])}const k=c(s,[["render",p]]);export{q as __pageData,k as default};
